import re

def parse_duration(s: str) -> int:
    pattern = r'(\d+)([hms])'
    total_seconds = 0

    for match in re.finditer(pattern, s):
        value = int(match.group(1))
        unit = match.group(2)

        if unit == 'h':
            total_seconds += value * 3600
        elif unit == 'm':
            total_seconds += value * 60
        elif unit == 's':
            total_seconds += value

    return total_seconds
